from ipaddress import ip_address, IPv6Address
from dataclasses import dataclass, field


@dataclass
class ConnectionDetails:
    """
    Class representing connection details for a REST API.
    This class encapsulates the necessary parameters to establish a connection.

    Attributes:
        host (str): The hostname or IP address of the REST API server.
        port (str): The port number for the REST API server.
        username (str): The username for authentication.
        password (str): The password for authentication.
        secure (bool): Whether to use HTTPS (True) or HTTP (False).
        timeout (float): Timeout for the connection in seconds.
        connection_name (str): A unique name for the connection.
        read_only (bool): Whether the connection is read-only.
        update_expired_password (bool): Whether to attempt to update expired passwords automatically.
    """
    host: str
    port: str
    username: str
    password: str
    secure: bool
    timeout: float
    connection_name: str
    read_only: bool
    update_expired_password: bool

    protocol: str = field(init=False)
    base_url: str = field(init=False)
    connection_id: str = field(init=False)

    def __post_init__(self):
        self.protocol = "https://" if self.secure else "http://"
        self.base_url = f"{self.protocol}{self.format_host_for_base_url(self.host)}:{self.port}"
        self.connection_id = f"{self.connection_name}_{id(self)}"

    @staticmethod
    def format_host_for_base_url(host: str) -> str:
        """
        Format the host for use in a base URL.
        If the host is an IPv6 address, it will be enclosed in square brackets.
        If it is an IPv4 address or a hostname, it will be returned as is.

        :param host: The host to format.

        :returns: Formatted host string suitable for use in a base URL.
        :rtype: str
        """
        host = host.rstrip("]").lstrip("[")
        try:
            if isinstance(ip_address(str(host)), IPv6Address):
                return f"[{host}]"
            else:
                return host

        except (ValueError, TypeError):
            return host
